//! Shared MCP transport trait and JSON-RPC framing helpers.//!//! Provides the [`McpTransport`] trait that all MCP transports implement,//! plus `write_jsonrpc_line` and `spawn_jsonrpc_reader` for newline-delimited//! JSON-RPC over byte streams (used by stdio and unix socket transports).use std::collections::HashMap;use std::sync::Arc;use async_trait::async_trait;use tokio::io::{AsyncBufRead, AsyncBufReadExt, AsyncWrite, AsyncWriteExt};use tokio::sync::{Mutex, oneshot};use tokio::task::JoinHandle;use crate::tools::mcp::protocol::{McpRequest, McpResponse};use crate::tools::tool::ToolError;/// Trait for sending JSON-RPC requests to an MCP server and receiving responses.////// Implementations handle the underlying transport (HTTP, stdio, unix socket, etc.).#[async_trait]pub trait McpTransport: Send + Sync {    /// Send a request and wait for the corresponding response.    ///    /// `headers` are used by HTTP-based transports (e.g., `Mcp-Session-Id`);    /// stream-based transports may ignore them.    async fn send(        &self,        request: &McpRequest,        headers: &HashMap<String, String>,    ) -> Result<McpResponse, ToolError>;    /// Shut down the transport, releasing any resources (child processes, connections).    async fn shutdown(&self) -> Result<(), ToolError>;    /// Whether this transport supports HTTP-specific features like session headers.    fn supports_http_features(&self) -> bool {        false    }}/// Serialize an [`McpRequest`] as a single JSON line and write it to `writer`.////// The line is terminated with `\n` and the writer is flushed.